float hash(float n) { return fract(sin(n) * 43758.5453); }
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float amount = U.p0.x;
    float t = floor(iTime * 12.0);
    float row = floor(uv.y * 24.0);
    float tear = step(0.92, hash(row + t)) * (hash(row * 3.1 + t) - 0.5) * amount * 6.0;
    uv.x = fract(uv.x + tear);
    float r = texture(iChannel0, uv + vec2(amount, 0.0)).r;
    float g = texture(iChannel0, uv).g;
    float b = texture(iChannel0, uv - vec2(amount, 0.0)).b;
    vec3 col = vec3(r, g, b);
    col *= 0.85 + 0.15 * sin(uv.y * iResolution.y * 3.14159);
    fragColor = vec4(col, 1.0);
}
